class Record(SequenceType):
    class data(ChoiceType):
        rootComponent = AdditiveNamedTypes(
            NamedType('asn1-Data', ASN1_Data()),
            NamedType('vendorExtensionData', VendorExtensionRecordData()),
        )
        componentType = rootComponent

    subtypeSpec = ExtensionMarker(True)
    rootComponent = AdditiveNamedTypes(
        OptionalNamedType('traceRecordingSessionRef', TraceRecordingSessionRef()),
        NamedType('sourceId', SynchronizationSourceId()),
        NamedType('seqNum', SequenceNumber()),
        NamedType('timestamp', UTC_Timestamp()),
        OptionalNamedType('crnti', C_RNTI()),
        OptionalNamedType('enb-ue-s1ap-Id', ENB_UE_S1AP_Id()),
        OptionalNamedType('mme-ue-s1ap-Id', MME_UE_S1AP_Id()),
        OptionalNamedType('gummei', GUMMEI()),
        DefaultedNamedType('direction', Direction('none')),
        NamedType('data', data()),
    )
    componentType = rootComponent


